#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 120
#define NCB 256

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static void pack_B(const float *B, float *Bp, int n, int pc, int kc, int s)
{
    int j0 = s * NR;
    float *dst = Bp + (size_t)s * NR * kc;
    if (j0 + NR <= n) {
        for (int k = 0; k < kc; k++)
            memcpy(dst + k * NR, B + (size_t)(pc + k) * n + j0, NR * sizeof(float));
    } else {
        int w = n - j0;
        for (int k = 0; k < kc; k++) {
            const float *src = B + (size_t)(pc + k) * n + j0;
            int j = 0;
            for (; j < w; j++) dst[k * NR + j] = src[j];
            for (; j < NR; j++) dst[k * NR + j] = 0.0f;
        }
    }
}

static void pack_A(const float *A, float *Ap, int n, int ic, int mc, int pc, int kc)
{
    int nstr = (mc + MR - 1) / MR;
    for (int r = 0; r < nstr; r++) {
        int i0 = ic + r * MR;
        int h = mc - r * MR;
        if (h > MR) h = MR;
        float *dst = Ap + (size_t)r * MR * kc;
        for (int i = 0; i < MR; i++) {
            if (i < h) {
                const float *src = A + (size_t)(i0 + i) * n + pc;
                for (int k = 0; k < kc; k++) dst[k * MR + i] = src[k];
            } else {
                for (int k = 0; k < kc; k++) dst[k * MR + i] = 0.0f;
            }
        }
    }
}

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int first)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += a0 * b0; c01 += a0 * b1;
        c10 += a1 * b0; c11 += a1 * b1;
        c20 += a2 * b0; c21 += a2 * b1;
        c30 += a3 * b0; c31 += a3 * b1;
        c40 += a4 * b0; c41 += a4 * b1;
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(i, x0, x1) do { \
            v8u *p0 = (v8u *)(c + (size_t)(i) * ldc); \
            v8u *p1 = (v8u *)(c + (size_t)(i) * ldc + 8); \
            if (first) { *p0 = x0; *p1 = x1; } \
            else { *p0 += x0; *p1 += x1; } \
        } while (0)
        ST(0, c00, c01); ST(1, c10, c11); ST(2, c20, c21);
        ST(3, c30, c31); ST(4, c40, c41); ST(5, c50, c51);
#undef ST
    } else {
        float tmp[MR][NR] __attribute__((aligned(32)));
        *(v8 *)&tmp[0][0] = c00; *(v8 *)&tmp[0][8] = c01;
        *(v8 *)&tmp[1][0] = c10; *(v8 *)&tmp[1][8] = c11;
        *(v8 *)&tmp[2][0] = c20; *(v8 *)&tmp[2][8] = c21;
        *(v8 *)&tmp[3][0] = c30; *(v8 *)&tmp[3][8] = c31;
        *(v8 *)&tmp[4][0] = c40; *(v8 *)&tmp[4][8] = c41;
        *(v8 *)&tmp[5][0] = c50; *(v8 *)&tmp[5][8] = c51;
        for (int i = 0; i < mr; i++) {
            float *cr = c + (size_t)i * ldc;
            if (first)
                for (int j = 0; j < nr; j++) cr[j] = tmp[i][j];
            else
                for (int j = 0; j < nr; j++) cr[j] += tmp[i][j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int nstrips = (n + NR - 1) / NR;
    size_t bsz = (size_t)KC * nstrips * NR * sizeof(float);
    float *Bp = (float *)aligned_alloc(64, bsz);
    int nib = (n + MC - 1) / MC;
    int njb = (n + NCB - 1) / NCB;

    #pragma omp parallel
    {
        float *Ap = (float *)aligned_alloc(64, (size_t)MC * KC * sizeof(float));

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

            #pragma omp for schedule(static)
            for (int s = 0; s < nstrips; s++)
                pack_B(B, Bp, n, pc, kc, s);

            #pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < nib * njb; t++) {
                int ib = t / njb, jb = t % njb;
                int ic = ib * MC;
                int mc = n - ic < MC ? n - ic : MC;
                int jc = jb * NCB;
                int jend = jc + NCB < n ? jc + NCB : n;

                pack_A(A, Ap, n, ic, mc, pc, kc);

                for (int j = jc; j < jend; j += NR) {
                    int nr = jend - j < NR ? jend - j : NR;
                    const float *bp = Bp + (size_t)(j / NR) * NR * kc;
                    for (int i = 0; i < mc; i += MR) {
                        int mr = mc - i < MR ? mc - i : MR;
                        const float *ap = Ap + (size_t)(i / MR) * MR * kc;
                        kernel(kc, ap, bp, C + (size_t)(ic + i) * n + j, n, mr, nr, first);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
